// Regenerates src/episodes/index.ts from the folders in src/episodes/.
import fs from "node:fs";
import path from "node:path";
const dir = path.join(process.cwd(), "src", "episodes");
const slugs = fs.readdirSync(dir).filter((d) => fs.existsSync(path.join(dir, d, "episode.json"))).sort();
const lines = [
  "// AUTO-GENERATED by scripts/sync-episodes.mjs. Do not edit by hand.",
  ...slugs.map((s, i) => `import ep${i} from "./${s}/episode.json";`),
  "",
  "export const episodes: Record<string, unknown> = {",
  ...slugs.map((s, i) => `  "${s}": ep${i},`),
  "};",
  "",
];
fs.writeFileSync(path.join(dir, "index.ts"), lines.join("\n"));
console.log(`Registered ${slugs.length} episode(s): ${slugs.join(", ") || "(none)"}`);
